    mut doubled = {name.copy(): price * 2 for name, price in prices.items() if price > 2}
    mut squares = {x: x * x for x in range(5)}
    mut paired = {k.copy(): v for k, v in zip(["a", "b"], [10, 20])}
    return doubled["fig"] + squares[4] + paired["a"] + len({c for c in "hello"}) + 2

